import random


class _Rules(Rules):
    """ActionAliasPermute (A axis, harder with DOSE): permute the mapping between command
    tokens and their effects for a deterministic (seeded by task_id) subset of commands.
    At DOSE=0 no commands are permuted; at DOSE=1 every admissible command token is
    remapped to a different command's effect. The permutation is a derangement so no token
    keeps its original effect, which forces the policy to discover the new mapping."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _perm(self, commands):
        rng = random.Random(f"{self.TASK_ID}:alias")
        idx = list(range(len(commands)))
        rng.shuffle(idx)
        # derangement: shift by a random nonzero offset
        k = rng.randrange(1, len(commands))
        n = int(self.DOSE * len(commands))
        mapping = {}
        for i in range(n):
            mapping[commands[i]] = commands[idx[(i + k) % len(commands)]]
        return mapping

    def modify_action(self, action, env_state):
        commands = list(getattr(env_state, "admissible_commands", []) or [])
        if not commands or self.DOSE <= 0:
            return action
        mapping = self._perm(commands)
        if action in mapping:
            return Action(mapping[action])
        return action

    def filter_observation(self, obs, env_state):
        return obs

