    TASK_ID = __TASK_ID__

    def _replaced(self, step, word_index):
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}:{word_index}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        text = obs.text
