class _Rules(Rules):
    """CommandTypo (O axis, harder with DOSE): corrupt the admissible-commands footer by
    replacing a deterministic fraction DOSE of the command strings with near-miss typos.
    The world is untouched, so the task is solvable by construction; the agent must recover
    the intended command from context. bucket = sha256(f"{task_id}:{cmd}")[:8] % 10000;
    corrupted iff bucket < DOSE * 10000, so the corrupted set is nested in DOSE."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _typo(self, cmd):
        if not cmd:
            return cmd
        # swap two adjacent characters (deterministic, reversible-looking near-miss)
        i = int(hashlib.sha256(f"{self.TASK_ID}:{cmd}".encode()).hexdigest()[:8], 16) % max(1, len(cmd) - 1)
        c = list(cmd)
        c[i], c[i + 1] = c[i + 1], c[i]
        return "".join(c)

    def _corrupted(self, cmd):
        digest = hashlib.sha256(f"{self.TASK_ID}:{cmd}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        cmds = (obs.data or {}).get("admissible_commands")
        if not cmds:
            return obs
        new_cmds = [self._typo(c) if self._corrupted(c) else c for c in cmds]
        data = dict(obs.data or {})
        data["admissible_commands"] = new_cmds
        text = obs.text
        for orig, new in zip(cmds, new_cmds):
            if orig != new:
                text = text.replace(orig, new)
        return Observation(text=text, data=data)

