class _Rules(Rules):
    """ActionTypo (A axis, harder with DOSE): with probability DOSE, a single character of the
    chosen command is perturbed (deterministically per step), turning it into an invalid or
    unintended command. The environment is otherwise untouched; the policy can recover by
    re-issuing the command on a later step."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def modify_action(self, action, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        if (int(digest[:8], 16) % 10000) >= int(self.DOSE * 10000):
            return action
        text = getattr(action, "text", None) or ""
        if not text.strip():
            return action
        idx = int(digest[8:12], 16) % len(text)
        c = text[idx]
        if c.isalpha():
            repl = 'a' if c.lower() != 'a' else 'b'
        elif c.isdigit():
            repl = '0' if c != '0' else '1'
        else:
            repl = ' '
        return Action(text=text[:idx] + repl + text[idx + 1:])

