class _Rules(Rules):
    """CommandAliasSwap (O axis, harder with DOSE): rewrite the admissible-commands footer so a
    deterministic fraction DOSE of the command names are replaced by opaque aliases (e.g.
    'cmd_3f2a'). The aliases are stable across steps for a given task, so the task stays solvable
    by learning the mapping, but the observation grows harder to parse as DOSE rises."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _alias(self, name):
        digest = hashlib.sha256(f"{self.TASK_ID}:{name}".encode("utf-8")).hexdigest()
        return f"cmd_{digest[:6]}"

    def _aliased(self, name):
        digest = hashlib.sha256(f"{self.TASK_ID}:{name}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        names = (obs.data or {}).get("admissible_commands")
        if not names:
            return obs
        new_names = [self._alias(n) if self._aliased(n) else n for n in names]
        data = dict(obs.data or {})
        data["admissible_commands"] = new_names
        text = obs.text
        for n, a in zip(names, new_names):
            text = text.replace(f"{n}", f"{a}")
        return Observation(text=text, data=data)

class _Rules(Rules):
    """RewardDelay (T axis, harder with DOSE): withhold the terminal success reward for
    ceil(DOSE * K) extra steps after success, requiring the agent to keep the goal state stable.
    K = __K__. The world is untouched; only the reward timing is stretched, so a persistent
    policy still succeeds."""

    DOSE = __DOSE__
    K = __K__

    def modify_transition(self, action, raw_response, env_state):
        delay = int(round(self.DOSE * self.K))
        if delay <= 0:
            return raw_response
        if raw_response.info.get("success") is True or bool(getattr(env_state, "won", False)):
            step = int(getattr(env_state, "step_count", 0) or 0)
            if step < delay:
                return EnvResponse(
                    observation=raw_response.observation,
                    reward=0.0,
                    terminated=False,
                    truncated=False,
                    info={**raw_response.info, "reward_delay": delay, "success": True},
                )
        return raw_response

