class _Rules(Rules):
    """CommandObfuscation (O axis, harder with DOSE): with probability DOSE each step,
    replace the names of admissible commands in the observation text with random hex tokens,
    preserving a deterministic mapping within the episode so the task remains logically solvable
    (the agent can still act by position or by learning the mapping). World is untouched."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _obfuscate(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._obfuscate(env_state):
            return obs
        text = obs.text
        marker = "\n\nAdmissible commands: "
        cut = text.find(marker)
        if cut < 0:
            return obs
        head = text[:cut + len(marker)]
        tail = text[cut + len(marker):]
        import re
        words = re.findall(r"[A-Za-z_][A-Za-z0-9_]*", tail)
        mapping = {}
        for w in words:
            if w not in mapping:
                mapping[w] = "cmd_" + hashlib.sha256((self.TASK_ID + w).encode("utf-8")).hexdigest()[:6]
        for w, tok in mapping.items():
            tail = re.sub(r"\b" + re.escape(w) + r"\b", tok, tail)
        return Observation(text=head + tail, data=dict(obs.data or {}))

class _Rules(Rules):
    """SuccessLabelNoise (O axis, harder with DOSE): with probability DOSE, hide the success
    signal in the terminal observation (but do not change the actual termination/reward). The
    environment dynamics are untouched, so the task remains solvable by construction; the agent
    just loses the explicit confirmation at higher DOSE."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _masked(self, env_state):
        import hashlib
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._masked(env_state):
            return obs
        text = obs.text
        for token in ("success", "succeeded", "completed", "done", "Correct", "correct"):
            text = text.replace(token, "...")
        data = dict(obs.data or {})
        for k in list(data.keys()):
            if "success" in str(k).lower():
                data.pop(k, None)
        return Observation(text=text, data=data)

class _Rules(Rules):
    """ActionAliasShift (A axis, harder with DOSE): with probability DOSE, rewrite the
    action string by replacing the leading verb with a synonym alias from a fixed table.
    The world accepts both forms, so the task remains solvable (the policy must learn the
    aliases)."""

    DOSE = __DOSE__

    ALIASES = {
        "go": "move",
        "take": "grab",
        "open": "unlock",
        "use": "apply",
        "look": "examine",
    }

    def modify_action(self, action):
        import random
        if random.random() >= self.DOSE:
            return action
        parts = action.split(None, 1)
        if not parts:
            return action
        head = parts[0].lower()
        if head in self.ALIASES:
            rest = parts[1] if len(parts) > 1 else ""
            return (self.ALIASES[head] + (" " + rest if rest else ""))
        return action

class _Rules(Rules):
    """ObservationNoiseTypos (O axis, harder with DOSE): corrupt a deterministic fraction DOSE
    of tokens in the observation text with character-level typos (swap adjacent chars). The
    admissible-commands footer and data dict are preserved verbatim, so the task stays solvable."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _corrupt(self, text):
        import hashlib
        words = text.split(" ")
        out = []
        for i, w in enumerate(words):
            seed = f"{self.TASK_ID}:{i}"
            digest = hashlib.sha256(seed.encode("utf-8")).hexdigest()
            if (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000) and len(w) > 1:
                j = int(digest[8:12], 16) % (len(w) - 1)
                w = w[:j] + w[j+1] + w[j] + w[j+2:]
            out.append(w)
        return " ".join(out)

    def filter_observation(self, obs, env_state):
        text = obs.text
        cut = text.find("\n\nAdmissible commands: ")
        if cut >= 0:
            body, footer = text[:cut], text[cut:]
            return Observation(text=self._corrupt(body) + footer, data=obs.data)
        return Observation(text=self._corrupt(text), data=obs.data)

